Ext.define('BNK.view.common.FileUploadPopupV1ViewController', {
    extend: 'BaseViewController',
    alias: 'controller.FileUploadPopupV1ViewController',

    config: {
        viewId: 'FileUploadPopupV1'
    },

    changeFile: function(field, newValue, oldValue, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            file = field.getFiles()[0],
            form = refs.form.el.dom,
            mb = 5 * 1024 * 1024;	// 1MB

            refs.infoField.setHtml("업로드 중...");
            refs.form.setHidden(true);
            debugger;
            Ext.Ajax.request({
                method : 'POST',
                headers : {
                    serviceId : 'COMFIL0010C01.singleFileUploadToTempDir',
                    viewId : me.getViewId(),
                    scope : me,
                },
                isUpload : true,
                jsonData : {
                    fileId      : null,
                    encrypt     : null, // 암복호화 여부
                    maxFileSize : null, // 파일용량제한
                },
                form : form,
                success : function(response, scope) {
                    var res = Ext.JSON.decode(response.responseText);
                    if (res && res.result && res.result.details) {
                        var result = res.result,
                            details = result.details;
                        vm.set('dtlFileId', details.id);
                        vm.set('fileExt', details.fileExt);
                        vm.set('orgnFileNm', details.orgnFileNm);
                        vm.set('fileNm', details.orgnFileNm + '.' + details.fileExt);
                        vm.set('fileSize', details.fileSize);
                        vm.set('fileId', result.id);

                        me.onBtnSave();
                    }
                    else if(!Ext.isEmpty(res.errMsg)){
                        refs.infoField.setHtml(res.errMsg);
                    }
                },
                failure : function(response){
                    var res = Ext.JSON.decode(response.responseText);

                    console.log(res);

                    Ext.Msg.show({
                        title : res.errTitle,
                        message : res.errMsg,
                        buttons : {
                            yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                        },
                        alwaysOnTop : true
                    });

                    refs.infoField.setHtml('※파일 크기는 5MB이하 로 업로드 바랍니다.');
                    refs.form.setHidden(false);
                }
            });

        // if (file.size > mb) {
        //     Ext.Msg.show({
        //         title : '알림',
        //         message : '해당 파일은 첨부할 수 없습니다.',
        //         buttons : {
        //             yes : {itemId : Ext.MessageBox.YES, text : '확인'}
        //         },
        //         alwaysOnTop : true,
        //         fn : function() {
        //             field.reset();
        //         }
        //     });
        // } else {

        // }
    },

    onFilefieldChange: function(field, newValue, oldValue, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            file = field.getFiles()[0];

        if (!file) {
            Ext.Msg.show({
                title : '알림',
                message : '파일을 선택해주세요.',
                buttons : {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                alwaysOnTop : true
            });
            return;
        }

        if (file.size > 5 * 1024 * 1024) {
            Ext.Msg.show({
                title : '알림',
                message : '파일 크기는 5MB 이하로 업로드 가능합니다.',
                buttons : {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                alwaysOnTop : true
            });
            return;
        }

        var reader = new FileReader();
        reader.onload = function(e) {
            var base64File = e.target.result.split(',')[1]; // "data:..." 제거

            Ext.Ajax.request({
                method: 'POST',
                jsonData: {
                    fileName: file.name,
                    fileData: base64File,
                    fileId: null,
                    encrypt: null,
                    maxFileSize: null
                },
                headers: {
                    serviceId: 'COMFIL0010C01.singleFileUploadToTempDir',
                    viewId: me.getViewId()
                },
                success : function(response, scope) {
                    var res = Ext.JSON.decode(response.responseText);
                    if (res && res.result && res.result.details) {
                        var result = res.result,
                            details = result.details;
                        vm.set('dtlFileId', details.id);
                        vm.set('fileExt', details.fileExt);
                        vm.set('orgnFileNm', details.orgnFileNm);
                        vm.set('fileNm', details.orgnFileNm + '.' + details.fileExt);
                        vm.set('fileSize', details.fileSize);
                        vm.set('fileId', result.id);

                        me.onBtnSave();
                    }
                    else if(!Ext.isEmpty(res.errMsg)){
                        refs.infoField.setHtml(res.errMsg);
                    }
                },
                failure : function(response){
                    var res = Ext.JSON.decode(response.responseText);

                    console.log(res);

                    Ext.Msg.show({
                        title : res.errTitle,
                        message : res.errMsg,
                        buttons : {
                            yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                        },
                        alwaysOnTop : true
                    });

                }
            });
        };

        reader.readAsDataURL(file);
    },

    onBtnSave: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            data = {
                dtlFileId : vm.get('dtlFileId'),			// COM_CMM_FILE_DTL
                fileExt : vm.get('fileExt'),
                orgnFileNm : vm.get('orgnFileNm'),
                fileNm : vm.get('fileNm'),
                fileSize : vm.get('fileSize'),
                fileId : vm.get('fileId'),				// COM_CMM_FILE
            };

        if (refs.file.getValue()) {
            me.getView().fireEvent('selected', data);
            me.getView().close();
        } else {
            Ext.Msg.show({
                title : '알림',
                message : '파일을 선택해주세요.',
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                alwaysOnTop : true
            });
        }
    },

    onBtnClose: function(button, e, eOpts) {
        this.getView().close();
    }

});